VALUES
('a2400000-0000-4000-8000-000000000001','video-editing-profesional','Video editing profesional','Editing video panjang maupun pendek untuk kebutuhan brand, bisnis, iklan, dan kreator.','Layanan editing dari materi video yang dikirim klien: pemotongan dan penyusunan alur, pacing, transisi seperlunya, color correction dasar, audio cleanup, subtitle/caption, format vertikal atau horizontal, dan file final sesuai brief. Ruang lingkup, jumlah revisi, durasi, lisensi aset, dan tenggat dikonfirmasi dalam penawaran sebelum pekerjaan dimulai.','editing',0,7,'published','live'),
('a2400000-0000-4000-8000-000000000002','short-form-content-studio','Short-form content studio','Paket video pendek untuk Reels, TikTok, Shorts, dan iklan sosial.','Produksi konten pendek dari footage, foto, atau brief klien: hook, struktur cerita, editing vertikal, subtitle, sound design, dan beberapa variasi format bila disepakati. Jumlah video, durasi, revisi, hak penggunaan, dan jadwal final ditetapkan dalam penawaran.','video',0,7,'published','live'),
('a2400000-0000-4000-8000-000000000003','motion-graphics-animation','Motion graphics & animasi','Animasi logo, tipografi bergerak, explainer, dan elemen visual promosi.','Pembuatan motion graphics untuk kebutuhan brand dan kampanye: animated titles, logo animation, kinetic typography, lower thirds, visual explainer, dan elemen grafis bergerak. Brief, storyboard, durasi, format ekspor, dan lisensi aset dikonfirmasi sebelum produksi.','motion',0,7,'published','live'),
('a2400000-0000-4000-8000-000000000004','desain-grafis-kreatif','Desain grafis kreatif','Desain materi promosi, sosial media, presentasi, dan kebutuhan visual bisnis.','Desain grafis untuk materi digital dan cetak: social media creative, poster, banner, thumbnail, presentasi, katalog, dan materi promosi. Termasuk penyesuaian ukuran dan file final sesuai paket yang disetujui.','desain',0,7,'published','live'),
('a2400000-0000-4000-8000-000000000005','brand-identity-design','Brand identity & visual system','Identitas visual dan panduan penggunaan merek untuk bisnis.','Pengembangan identitas visual berdasarkan brief: eksplorasi arah visual, logo, palet warna, tipografi, elemen pendukung, dan panduan dasar penggunaan. Riset nama merek, pendaftaran merek, dan pekerjaan di luar ruang lingkup harus disepakati terpisah.','branding',0,7,'published','live'),
('a2400000-0000-4000-8000-000000000006','ai-assisted-creative-studio','AI-assisted creative studio','Konsep visual, ide konten, storyboard, dan aset kreatif dengan bantuan AI.','Produksi kreatif berbantuan AI untuk eksplorasi konsep, storyboard, visual pendukung, variasi materi kampanye, dan draft konten. Hasil ditinjau manusia sebelum diserahkan. Model, batas penggunaan, hak komersial, penggunaan wajah/suara, dan kebutuhan lisensi dijelaskan pada penawaran.','ai',0,7,'published','live'),
('a2400000-0000-4000-8000-000000000007','social-media-creative-package','Social media creative package','Paket desain dan materi konten untuk kalender media sosial bisnis.','Paket kreatif media sosial yang dapat mencakup ide konten, caption, desain carousel, thumbnail, dan video pendek. Kanal, jumlah materi, jadwal, moderasi komentar, dan publikasi akun tidak termasuk kecuali disebutkan secara tertulis dalam penawaran.','social',0,7,'published','live'),
('a2400000-0000-4000-8000-000000000008','website-landing-page','Website & landing page','Website profil perusahaan, landing page kampanye, dan halaman produk.','Perancangan dan pengembangan website sesuai kebutuhan: struktur halaman, desain responsif, konten yang disediakan klien, formulir, integrasi yang disepakati, pengujian, dan serah terima. Domain, hosting, lisensi pihak ketiga, dan pemeliharaan berkelanjutan dihitung terpisah bila diperlukan.','website',0,7,'published','live')
